.dm-tk-st .dm-rl{position:absolute;left:7.5px;top:25px;bottom:-7px;width:1px;background:var(--dm-rail);transform-origin:top;transform:scaleY(0);transition:transform .6s var(--dm-ease)}
.dm-tk-st .dm-rl.dm-on{transform:scaleY(1)}
.dm-tk-st .dm-tx{min-width:0;display:flex;flex-direction:column;gap:8px}
.dm-tk-st .dm-lab{color:var(--dm-fg2);transition:color .5s var(--dm-ease)}
.dm-tk-st.dm-run .dm-lab{color:var(--dm-fg)}
.dm-tk-st.dm-dead .dm-lab,.dm-tk-st.dm-sub .dm-lab{color:var(--dm-muted)}
.dm-tk-st.dm-sub{padding-left:40px}
.dm-tk-st.dm-sub .dm-mk{left:15px}
.dm-tk-st.dm-sub .dm-curve{position:absolute;left:7.5px;top:-6px;width:11px;height:20px;border-left:1px solid var(--dm-rail);border-bottom:1px solid var(--dm-rail);border-bottom-left-radius:9px}
.dm-tk-st .dm-mk .dm-dot{width:6px;height:6px;color:var(--dm-faint)}
.dm-tk-st.dm-sub .dm-mk .dm-dot{width:4px;height:4px}
.dm-tk-st .dm-ring{width:8px;height:8px;border-radius:50%;border:1.3px solid var(--dm-muted)}
.dm-tk-chips{display:flex;flex-wrap:wrap;gap:6px}
.dm-tk-more{height:26px;padding:0 8px;border-radius:var(--dm-r-pill);font-size:12.5px;color:var(--dm-muted);align-self:center;transition:background var(--dm-t-fast),color var(--dm-t-fast)}
.dm-tk-more:hover{background:var(--dm-chip);color:var(--dm-fg)}
.dm-tk-fin .dm-mk{color:var(--dm-accent)}
.dm-tk-fin .dm-lab{color:var(--dm-fg)!important}
.dm-tk-fin .dm-sum{color:var(--dm-muted);margin-left:8px}

